import axios from "axios";
import api from "../lib/api";
import { getGoogleMerchantChoices, validateGoogleMerchantChoices } from "./googleMerchantObservationChoices";

jest.mock("../lib/api", () => ({ __esModule: true, default: { get: jest.fn() } }));

// Generated by actual choices.call(local_db()) on2026-10-29; synthetic DB only.
export const CHOICES = {
    source: "mezan_google_local_membership", owner_id: "synthetic-owner",
    observation_id: "4516b385-8b53-4cf5-b132-0c3a21c06a3a", observed_at: "2026-10-29T22:44:25.647604+00:00",
    local_membership: "matching_complete_bracketing_snapshots", local_set_complete: true, local_account_count: 2,
    ads_accounts: [{ account_id: "5052346701", display_name: "إعلانات المتجر" }],
    merchant_accounts: [{ merchant_id: "123", display_name: "كتالوج المتجر" }],
    remote_account_set_complete: false, native_link_verified: false, merchant_access_verified: false,
    continuous_authorization_proved: false, store_product_mapping_verified: false, ads_eligibility_verified: false,
    execution_authorized: false, provider_calls: 0, provider_writes: 0,
};
function sample() { return JSON.parse(JSON.stringify(CHOICES)); }

beforeEach(() => jest.clearAllMocks());
test("actual local backend shape preserves separate IDs and immutable nonauthorizing choices", () => {
    const parsed = validateGoogleMerchantChoices(sample(), "synthetic-owner");
    expect(parsed.adsAccounts[0].account_id).toBe("5052346701");
    expect(parsed.merchantAccounts[0].merchant_id).toBe("123");
    expect(parsed.ownerId).toBe("synthetic-owner");
    expect(Object.isFrozen(parsed)).toBe(true); expect(Object.isFrozen(parsed.adsAccounts[0])).toBe(true);
});
test.each(["remote_account_set_complete", "native_link_verified", "merchant_access_verified", "continuous_authorization_proved",
    "store_product_mapping_verified", "ads_eligibility_verified", "execution_authorized"])("refuses inflated claim %s", (field) => {
    const value = sample(); value[field] = true;
    expect(() => validateGoogleMerchantChoices(value, "synthetic-owner")).toThrow("UNPROVED");
});
test.each([null, 123, "0123", "1-23", "0", "9223372036854775808"])("refuses malformed native ID %s", (value) => {
    const body = sample(); body.merchant_accounts[0].merchant_id = value;
    expect(() => validateGoogleMerchantChoices(body, "synthetic-owner")).toThrow("UNPROVED");
});
test.each(["owner", "source", "partial", "count", "duplicates", "extra", "name", "date", "observation", "calls", "writes", "missing"])("refuses invalid complete-list contract %s", (kind) => {
    const value = sample();
    if (kind === "owner") value.owner_id = "other";
    if (kind === "source") value.source = "overview";
    if (kind === "partial") value.local_set_complete = false;
    if (kind === "count") value.local_account_count = 1;
    if (kind === "duplicates") { value.ads_accounts.push({ ...value.ads_accounts[0] }); value.local_account_count++; }
    if (kind === "extra") value.ads_accounts[0].selected = true;
    if (kind === "name") value.ads_accounts[0].display_name = "private\nname";
    if (kind === "date") value.observed_at = "not a date";
    if (kind === "observation") value.observation_id = "fake";
    if (kind === "calls") value.provider_calls = 1;
    if (kind === "writes") value.provider_writes = false;
    if (kind === "missing") delete value.native_link_verified;
    expect(() => validateGoogleMerchantChoices(value, "synthetic-owner")).toThrow("UNPROVED");
});
test.each([0, 400, 401])("validates the total account boundary %s", (count) => {
    const body = sample(); body.ads_accounts = [];
    body.merchant_accounts = Array.from({ length: count }, (_, i) => ({ merchant_id: String(i + 1), display_name: "حساب" }));
    body.local_account_count = count;
    if (count <= 400) expect(validateGoogleMerchantChoices(body, "synthetic-owner").merchantAccounts).toHaveLength(count);
    else expect(() => validateGoogleMerchantChoices(body, "synthetic-owner")).toThrow("UNPROVED");
});
test("manual service is one fixed GET with cancellation and no auth replay or arbitrary params", async () => {
    api.get.mockResolvedValue({ data: sample() }); const controller = new AbortController();
    await getGoogleMerchantChoices({ ownerId: "synthetic-owner", signal: controller.signal });
    expect(api.get).toHaveBeenCalledWith("/integrations-v2/google_ads/merchant-products/choices", {
        signal: controller.signal, timeout: 30000, _mezanAuthRetried: true,
    });
});
test("actual existing API interceptor does not refresh POST or replay this list GET after401", async () => {
    const realApi = jest.requireActual("../lib/api").default;
    const post = jest.spyOn(axios, "post"); const original = realApi.defaults.adapter;
    const adapter = jest.fn(async (config) => { const error = new Error("synthetic401"); error.config = config; error.response = { status: 401 }; throw error; });
    realApi.defaults.adapter = adapter; api.get.mockImplementation((...args) => realApi.get(...args));
    try {
        await expect(getGoogleMerchantChoices({ ownerId: "synthetic-owner", signal: new AbortController().signal })).rejects.toThrow("synthetic401");
        expect(adapter).toHaveBeenCalledTimes(1); expect(post).not.toHaveBeenCalled();
    } finally { realApi.defaults.adapter = original; post.mockRestore(); api.get.mockReset(); }
});
